-- Schema (matches EF Core / Npgsql output)
CREATE TABLE IF NOT EXISTS "Apartments" (
    "Id"      integer GENERATED BY DEFAULT AS IDENTITY,
    "Street"  text NOT NULL,
    "City"    text NOT NULL,
    "ZipCode" text NOT NULL,
    CONSTRAINT "PK_Apartments" PRIMARY KEY ("Id")
);

CREATE TABLE IF NOT EXISTS "Employees" (
    "Id"          integer GENERATED BY DEFAULT AS IDENTITY,
    "Name"        text NOT NULL,
    "Email"       text NOT NULL,
    "ApartmentId" integer NULL,
    CONSTRAINT "PK_Employees" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Employees_Apartments_ApartmentId"
        FOREIGN KEY ("ApartmentId")
        REFERENCES "Apartments" ("Id")
        ON DELETE SET NULL
);

-- Seed data
INSERT INTO "Apartments" ("Id", "Street", "City", "ZipCode") VALUES
    (1, 'Main Street',  'Springfield', '12345'),
    (2, 'Elm Street',   'Shelbyville', '54321'),
    (3, 'Oak Avenue',   'Ogdenville',  '67890');

INSERT INTO "Employees" ("Id", "Name", "Email", "ApartmentId") VALUES
    (1, 'John Doe',       'john.doe@example.com',       1),
    (2, 'Jane Smith',     'jane.smith@example.com',     2),
    (3, 'Alice Johnson',  'alice.johnson@example.com',  3);

-- Advance sequences so EF Core / test inserts don't collide with seeded IDs
SELECT setval(pg_get_serial_sequence('"Apartments"', 'Id'), MAX("Id")) FROM "Apartments";
SELECT setval(pg_get_serial_sequence('"Employees"',  'Id'), MAX("Id")) FROM "Employees";
